import com.praxicraft.assess.Webhooks; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec;
public class Main { public static void main(String[] a) throws Exception { String secret=System.getenv("PRAXICRAFT_WEBHOOK_SECRET"); byte[] raw="{\"type\":\"candidate.passed\"}".getBytes(); Mac mac=Mac.getInstance("HmacSHA256"); mac.init(new SecretKeySpec(secret.getBytes(),"HmacSHA256")); StringBuilder sb=new StringBuilder("sha256="); for(byte b:mac.doFinal(raw)) sb.append(String.format("%02x",b)); System.out.println(Webhooks.verifySignature(secret, raw, sb.toString())); } }
